#!/bin/sh
# Remove only rules owned by this project. Restores the AC's Internet access.
set -eu
for command in iptables ip6tables; do
    command -v "$command" >/dev/null 2>&1 || continue
    for table in nat filter; do
        "$command" -t "$table" -S 2>/dev/null | while IFS= read -r rule; do
            case "$rule" in
                *gree-local-cloud*)
                    # Rules are generated by this project and contain no shell text.
                    printf '%s\n' "$rule" | sed 's/^-A /-D /' | xargs "$command" -t "$table"
                    ;;
            esac
        done
    done
done
